public class Person
{
    private string name;

    public string Name
    {
        get { return name; }
        set { name = value; }
    }
}

var p = new Person();
p.Name = "Alice";
Console.WriteLine(p.Name);

public class Product
{
    // Compiler creates a backing field automatically
    public string Name { get; set; }
    public decimal Price { get; set; }
}

var p = new Product();
p.Name = "Widget";
Console.WriteLine(p.Name);

public class Counter
{
    public int Count { get; private set; }

    public Counter(int start)
    {
        Count = start;  // OK - inside the class
    }

    public void Increment() { Count++; }
}

var c = new Counter(10);
c.Increment();
Console.WriteLine(c.Count);  // 11
// c.Count = 5;  // ERROR - private set

public class Person
{
    private string email;

    public string Email
    {
        get { return email; }
        set
        {
            if (value.Contains('@'))
                email = value.ToLower();
        }
    }
}

var p = new Person();
p.Email = "BOB@example.com";
Console.WriteLine(p.Email);

